        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins overall (relative fill).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Spread awareness: if this bin is far below mean residual, penalize slightly
    // to balance residual distribution across bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: early in stream, allow more bins (less pressure);
    // late in stream, conserve bins, favor tight packing harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // New-bin candidate: baseline cost of opening a bin; cheaper early, expensive late,
    // and cheaper when many bins are already open relative to item count.
    if bin_residual == bin_capacity {
        let bin_pressure = if total_items > 0 {
            open_bins_count as f64 / (total_items as f64).sqrt()
        } else {
            0.0
        };
        score = 45.0 - progress * 10.0 - bin_pressure * 6.0;
        // If the item would leave a perfect next-fit hole in a new bin, encourage it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Avoid opening a new bin when a decent existing fit exists.
        if post_residual > 0 && post_residual < 20 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with progress:
    // early in the stream, waste matters less; late, penalize waste quadratically.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * pr_norm * pr_norm * cap * 0.5;

    // Penalize leaving residuals that are too small to be useful later,
    // smoothly via a parabola centered at mid-range residuals.
    let ideal = 40.0 + 20.0 * progress;
    let dev = pr - ideal;
    score += 0.02 * dev * dev;

    // Reward tight fits (small post_residual) with a cubic discount.
    score -= (1.0 - pr_norm).powi(3) * item_size as f64 * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Smooth penalty if next item won't fit here afterward
        let gap = next_item_size as f64 - pr;
        score += 0.05 * gap * gap * (0.5 + progress);
    }

    // Encourage consolidation: bins below mean residual are slightly favored.
    score += 0.05 * (mean_residual - pr);

    // Mild penalty for proliferating open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "reusable" residue classes (multiples of 10/20) are more valuable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 20 == 0 {
        -25.0
    } else if pr % 10 == 0 {
        -15.0
    } else if pr <= 9 {
        30.0 // dead space: too small for any realistic item
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item slots perfectly or near-perfectly
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 + 2.0 * slack.min(20.0) as f64;
            if pr == next_item_size {
                score -= 30.0; // exact chain fit
            }
        } else {
            // next item cannot use this bin's leftover; penalize by gap size
            let gap = (next_item_size - pr) as f64;
            score += gap.min(30.0);
        }
        // Harmonic check: next item pairs with current to leave a round leftover
        let two_step = pr.saturating_sub(next_item_size);
        if two_step % 10 == 0 && next_item_size <= pr {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless
    // current bin would create dead space.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 - (fitting_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big next item: a fresh bin is attractive
        }
    }

    // Mild pressure to prefer tighter bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * progress;
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful for future items are heavily penalized (non-linearly).
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 18.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Tight-but-usable fit: mild reward for leaving large reusable space.
    if post_residual >= 40 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Next item would be blocked by this placement: penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 6.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward being fully consumed (tighter than average).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 3.0 / (1.0 + dev);

    // Early stream: allow more freedom; late stream: tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step lookahead match: this bin's post residual
    // exactly fits the next item (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0) * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that is larger than next item but too small
        // to be useful relative to mean residual (dead space creation).
        if post_residual > next_item_size && (post_residual as f64) < mean_residual * 0.5 {
            score += 15.0;
        }
    } else {
        // Last item: prefer minimal post residual (best fit).
        score += 20.0;
    }

    // Penalize unusable dead space: residual below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere (large item, tight open bins).
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.2;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 20.0; // fresh bin sets up a perfect next placement
        } else if tight || item_size > bin_capacity / 2 {
            score -= 5.0;
        } else {
            score += 45.0; // discourage wasteful new bins when a decent fit exists
        }
    }

    // Mild preference for tighter-than-average bins to consolidate fragments.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, compact more aggressively (fewer leftover fragments).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Penalize large dead space, especially when it can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving space that fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Exact match with next item is excellent.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            score += 5.0; // dead space relative to lookahead
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins for big items);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tightness = 10.0 * progress;
    score -= tightness * (bin_residual as f64 / bin_capacity as f64);
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64 / 10.0);

    // Prefer bins with residual close to mean (balanced packing) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - progress) * 0.15 * dev;

    // Global pressure: many open bins -> favor filling existing ones.
    if open_bins_count > 8 {
        score -= 0.5 * (open_bins_count as f64 - 8.0);
    }

    // New-bin candidate: only attractive when item is large relative to residual space
    // of a fresh bin and stream is early / mean residual is low.
    if bin_residual == bin_capacity {
        score += 12.0; // base cost of opening a new bin
        if item_size >= 50 {
            score -= 6.0;
        }
        if progress > 0.7 {
            score += 10.0; // late stream: avoid opening bins
        }
        if mean_residual > 20.0 {
            score += 8.0; // existing bins have room; don't open new
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // room to co-pack next item in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual (good fit), with sharpening as stream progresses
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Non-linear penalty for medium dead space: residual that is too large to be useful
    let dead_zone = ((pr / cap) - 0.25).powi(2);
    score += 18.0 * dead_zone * (pr / cap);

    // Reward near-perfect fits smoothly
    score -= 12.0 * (-pr / 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        if fits_next {
            score -= 6.0 * (1.0 - pr / cap);
        } else {
            score += 4.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Mild penalty when bin is far below mean residual (keeps bins balanced)
    score += 0.3 * (mean_residual - pr).abs() / cap;

    // Slight preference for filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: tightness reward — the smaller the post residual, the better.
    score -= (item_size as f64 / cap) * 30.0;

    // Harmonic class of the post residual modulo capacity quartiles.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..3 harmonic class
    match class {
        0 => score -= 12.0,                       // near-perfect fit class
        1 => score += 4.0,                        // awkward quarter leftover
        2 => score += 8.0,                        // half-empty dead zone
        _ => score += 2.0,                        // nearly empty bin
    }

    // Fine harmonic: post_residual divisible by small units is reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 3 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: can next item fit into post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Harmonic match: next item lands in a good class after placement.
        let next_post = post_residual - next_item_size;
        if next_post < quarter {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize stranding a large dead zone.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive early
    // in the stream or when open bins are badly fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = cap - (item_size as f64); // neutral baseline for empty bin
        score += open_bins_count as f64 * 3.0; // penalize proliferation
        if progress < 0.3 {
            score -= 15.0; // early stream: cheap to open bins
        }
        if mean_residual > cap * 0.6 && open_bins_count > 2 {
            score += 20.0; // open bins are roomy; don't open more
        }
    }

    // Fragmentation penalty relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.4 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much harder
    // than large ones. A gap is "dead" if it is too small for typical items
    // (items >= 10 in classic regime, but sizes 1..100 here): treat gaps
    // below a fraction of capacity as wasted.
    let gap = post_residual as f64;
    if gap > 0.0 {
        let dead_threshold = bin_capacity as f64 * 0.25;
        if gap < dead_threshold {
            // The smaller the gap, the more it costs per unit.
            score += (dead_threshold - gap) * 3.0;
        }
        // Perfect fit bonus: consume the bin entirely.
        if gap == 0.0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to the bin's current residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins as the stream progresses
    // and as more bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (12.0 + 30.0 * open_bins_count as f64 * (0.5 + progress));

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward leaving that exact space; otherwise penalize leaving a gap
    // the next item cannot use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Slight preference for bins with residual below the mean (consolidate
    // small leftovers rather than fragmenting large ones).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item can also fit here: reward proportional to leftover after both
            let both_left = post_residual as f64 - next_item_size as f64;
            score -= 30.0 - both_left * 0.5;
        } else {
            // next item won't fit here: penalize leaving awkward dead space
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates favorably from mean (keep mean spread balanced)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Tight fit reward: small post residual is good
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Early in stream: slightly prefer opening new bins to build flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is close to the item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Reward exact or near-exact fills hard.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits in the post-residual, this is a great pairing.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 - 0.15 * slack_after_next as f64;
        } else {
            // Post-residual too small for next item: penalize proportionally to wasted space.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 15 {
            score -= 15.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // is large or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins mildly; relax as the stream grows and bins accumulate.
        let mut new_bin_penalty = 18.0 + 4.0 * (open_bins_count as f64).sqrt();
        // If the item is big, a fresh bin is reasonable (less penalty).
        if item_size >= 50 {
            new_bin_penalty -= 10.0;
        }
        // If mean residual is large, existing bins have room; discourage new bin.
        if mean_residual > item_size as f64 + 10.0 {
            new_bin_penalty += 10.0;
        }
        // Early in the stream, avoid fragmenting; late, allow more bins.
        new_bin_penalty *= 1.0 - 0.25 * progress;
        score += new_bin_penalty.max(2.0);
    }

    // Slight preference for bins whose residual deviates from the mean (consolidate).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Mild cap on open bins: many open bins with small residuals is fragmentation.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * (0.5 + progress)
