            score -= 7.0;
        }
        // Fresh bin for mid-size item when only scraps remain is attractive.
        if item_size >= 30 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        // Fresh bin for a large item whose size pairs with next item.
        if item_size >= 45 && next_item_size >= 45 && (item_size + next_item_size) as f64 <= cap {
            score -= 10.0;
        }
    }

    // Harmonic band match when multiple bins fit.
    if next_item_size > 0 && pr >= next_item_size && fitting_bins_count > 1 {
        score -= 6.0 + 3.0 * (1.0 - progress);
    }

    // MUTATION: exact-fill drive — item exactly consumes the bin, bonus scaled by progress.
    if pr == 0 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // MUTATION: avoid leaving residuals in the "awkward middle" band (17-23)
    // that rarely hosts typical items, scaled by how much next item misses.
    if pr >= 17 && pr <= 23 && next_item_size > pr {
        score += 8.0;
    }

    // Consolidation pressure: prefer bins in low-mean-residual regimes.
    score -= 0.07 * mean_residual;

    // Progress-scaled tightening: late in the stream, prefer filling existing bins.
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual;
    let cap = (bin_capacity as f64).max(1.0);
    let frac = pr as f64 / cap;

    // Tight-fit rewards: perfect and near-perfect closures (amplified, extended).
    if pr == 0 {
        score -= 96.0;
    } else if pr <= 4 {
        score -= 58.0;
    } else if pr <= 8 {
        score -= 34.0;
    } else if pr <= 12 {
        score -= 18.0;
    } else if pr <= 18 {
        score -= 7.5;
    } else if pr <= 26 {
        score -= 2.0;
    } else if pr <= 34 {
        score += 3.0;
    }

    // Dead-space sliver classes.
    if pr > 0 && pr < 9 {
        score += 42.0;
    } else if pr < 18 {
        score += 13.0;
    } else if pr % 20 == 0 {
        score -= 20.0;
    } else if pr % 25 == 0 {
        score -= 10.0;
    }

    // Residual-fraction coupling.
    if frac > 0.5 {
        score += 13.5 * (frac - 0.5);
    } else if frac < 0.15 && pr > 0 {
        score -= 8.0 * (0.15 - frac) * 10.0;
    }

    // Dead-space ratio vs next item.
    if next_item_size > pr && pr > 0 {
        let dead_ratio = 1.0 - pr as f64 / (next_item_size as f64).max(1.0);
        score += 11.0 * dead_ratio * frac.max(0.2);
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 52.0;
