        // Fresh bin for a large item whose size pairs with next item.
        if item_size >= 45 && next_item_size >= 45 && (item_size + next_item_size) as f64 <= cap {
            score -= 10.0;
        }
        // MUTATION: refine — when no existing bin fits well (all residuals far
