    let min_useful = 10u32.min(item_size);
    if post_residual < min_useful {
        score += 60.0;
    } else if post_residual <= 15 {
        // Small but potentially usable gap: mild penalty to prefer tighter fits.
        score += 8.0;
    }

    // Reward near-perfect fills.
