    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on (t small): prefer tight fits, penalize large post_residual mildly.
    // Later (t large): dead space becomes more costly, weight grows.
    let mut score = post * (1.0 + 2.0 * t * t);

    // Cubic smooth term: strongly punish very small post_residual only late in stream
    // (tiny slivers are dead space), but early they are acceptable.
    let norm_post = post / cap;
    score += 12.0 * norm_post * norm_post * norm_post * (0.5 + t);

    // Reward near-perfect fills (smooth bump around post_residual ~ 0..5)
    let fill_quality = 1.0 - norm_post;
    score -= 10.0 * fill_quality * fill_quality * fill_quality * (1.0 - t);

    // Lookahead coupling: if next item fits the post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * t;
    } else if next_item_size > 0 {
        // smooth penalty for wasted lookahead opportunity
        let gap = (next_item_size as f64 - post) / cap;
        score += 5.0 * gap * gap;
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // mild preference for fuller bins when many choices
        score -= 2.0 / (fitting_bins_count as f64);
