    // no open bin is a good fit (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        score = post + 8.0 * norm_post * (1.0 + t) + 4.0;
        if fitting_bins_count == 1 {
            score -= 20.0; // still allow new bin if it's effectively the only option
        }
