    // Base: reward tight fits (small post_residual) with a harmonic weight.
    let post_frac = post_residual as f64 / cap;
    score += post_frac * post_frac * 30.0;

    // Harmonic class of post_residual: dead space below smallest item (1..10) is worthless.
    if post_residual < 10 {
