    // (multiples of 10/20) is reusable by typical item sizes.
    let class = post_residual / 20;
    if class * 20 == post_residual && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 - slack * 0.15;
        if (post_residual - next_item_size) == 0 {
            score -= 12.0; // perfect chaining
        }
    } else if next_item_size > post_residual {
        // next item can't use this residual: penalize proportionally to waste.
        score += (next_item_size - post_residual) as f64 * 0.10;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild default penalty so it
    // wins only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.25 + (open_bins_count as f64) * 0.5;
    } else {
