        // Two-step lookahead: reward residuals hosting next item with a useful remainder.
        if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem >= 4 && rem <= 16 {
                score -= 6.0 * (1.0 - rem as f64 / 16.0);
