    if next_item_size > 0 && pr > next_item_size {
        let rem = pr - next_item_size;
        if rem >= 1 && rem <= 3 {
            score += 10.0;
        }
    }

    // Consolidation pressure.
    score -= 0.07 * mean_residual;

    // Progress-scaled tightening.
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity.
    let mut score = post;

    // Smooth non-linear coupling: post_residual^2 normalized, modulated by progress.
    // Early in stream, squandering space is cheap; late, dead space is costly.
    let dead = (post / cap).powi(2) * cap;
    score += dead * (0.2 + 1.3 * progress);

    // Perfect fit bonus: cubic smooth reward as post_residual -> 0.
    score -= 12.0 * (1.0 - post / cap).powi(3);

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            // smooth reward for leaving a usable remainder, penalize tiny unusable slivers
            score -= 6.0 * (1.0 - slack).powi(2);
            score += 4.0 * slack.powi(2);
        } else {
            // next item cannot fit: penalize proportionally to overflow gap
            score += 3.0 * ((nxt - post) / cap).powi(2) * cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this bin is far from mean residual
    // (encourages consolidation of similar residual bins).
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev.powi(2) * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity or open bins are all poor fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let poor_fits = (post_residual == 0) as i32 as f64; // placeholder, never true for empty
        let _ = poor_fits;
        let mean_use = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 - 10.0 * fill_ratio.powi(2) - 4.0 * mean_use * progress;
    }

    score
}

