            if rem % 10 == 0 || (rem % 5 == 0 && rem <= 20) {
                score -= 15.0;
            }
            if rem >= next_item_size / 2 {
                score -= 4.5;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.10;
            if pr < 14 {
                score += 13.0;
            } else if next_item_size - pr <= 5 {
                score += 6.5;
            }
            if pr >= 18 {
                score += 3.0 + 3.5 * progress;
            }
            if next_item_size >= 45 && pr < 20 {
                score += 9.5;
            }
        }
        if next_item_size >= 10 && next_item_size <= 40 && pr > 0 && (pr as i64 - next_item_size as i64).abs() <= 2 {
            score -= 8.5;
        }
        let after = pr.saturating_sub(next_item_size);
        if after > 0 && after <= 8 {
            score -= 12.0;
        } else if after > 8 && after <= 16 {
            score -= 5.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 48.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 24;
        let big_item = item_size >= 50;
        if poor_fit || big_item {
            score -= 28.0;
        } else {
            score += 49.0 + mean_residual * 0.20 + (open_bins_count as f64) * 0.4;
        }
        if next_item_size >= 60 {
            score -= 16.0;
        }
        if progress > 0.6 {
            score += 22.0 * progress;
        }
        if open_bins_count < 4 {
            score -= 8.5;
        }
        if item_size <= 20 && pr <= 20 {
            score += 15.0;
        }
        if progress > 0.75 && open_bins_count > 6 {
            score += 13.0;
        }
        if progress < 0.25 && open_bins_count <= 8 {
            score -= 5.5;
        }
        if item_size <= 10 && progress > 0.35 {
            score += 10.0;
        }
        if item_size >= 30 && fitting_bins_count <= 2 {
            score -= 11.5;
        }
        if item_size >= 45 && next_item_size >= 45 && (item_size + next_item_size) as f64 <= cap {
            score -= 9.5;
        }
        // Fresh-bin appeal when item matches mean residual closely.
        if item_size >= 25 && mean_residual > 0.0 && (mean_residual - item_size as f64).abs() < 4.0 {
            score -= 8.5;
        }
        // MUTATION: open a fresh bin when the item pairs with the next item exactly
        // (item + next == capacity), guaranteeing a perfect closure.
        if next_item_size > 0 && (item_size + next_item_size) as f64 == cap {
            score -= 14.0;
