        score += (bin_residual as f64 - mean_residual) * 0.08;
    }

    // Harmonic band match when multiple bins fit.
    if next_item_size > 0 && pr >= next_item_size && fitting_bins_count > 1 {
        score -= 5.5 + 3.0 * (1.0 - progress);
    }

    // Avoid awkward-middle residuals when next item overshoots.
    if pr >= 17 && pr <= 23 && next_item_size > pr {
        score += 7.5;
    }
    if pr > 30 && next_item_size > pr {
        score += 0.23 * (pr - 30) as f64;
    }

    // Exact-fill drive.
    if pr == 0 && bin_residual < bin_capacity {
        score -= 18.0 + 14.0 * progress;
    }

    // Consolidation pressure.
    score -= 0.065 * mean_residual;

    // Late-stream tightening.
    score -= progress * 6.0 * (post_frac * 10.0).min(1.0);
    score += (open_bins_count as f64) * 0.27;
    score *= 1.0 - 0.13 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; residuals in the "hard to fill" band are penalized extra.
    let r = post_residual as f64;
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if post_residual < 10 {
        // dead space below the classic small-item band: heavily penalize
        score += 45.0 - r * 2.0;
    } else if post_residual <= 20 {
        // awkward gap: only fillable by small items
        score += 12.0 - r * 0.2;
    }

    // Reward tight fits relative to item size (waste ratio).
    let waste_ratio = r / (item_size.max(1) as f64);
    score += waste_ratio * 4.0;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0; // sets up a near-perfect chain
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // kills the lookahead opportunity
        }
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // unless this bin is the last chance for the item.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 4.0 * progress);
    score += pressure;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0; // last-chance bin: strongly prefer using it
    }

    // New-bin candidate handling: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Prefer a new bin when open bins have poor mean residual structure
        // (lots of scattered dead space) or few bins are open early on.
        let dead_mean = (mean_residual - r).max(0.0);
        if dead_mean > 25.0 || open_bins_count == 0 {
            score -= 14.0;
        } else {
            score += 20.0; // keep using existing bins when they are healthy
        }
    }

    // Mild preference for bins whose residual is close to the mean (balance).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

