        x if x % 20 == 0 => 25.0,
        x if x % 10 == 0 => 18.0,
        x if x % 5 == 0 => 8.0,
        _ => -6.0,
    };
    score -= class_bonus;

    // Tight-fit reward: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus via integer division threshold.
    if pr == 0 {
        score -= 100.0;
    } else if bin_residual <= 2 * item_size && pr <= 10 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 10 {
            score -= 25.0;
        } else if next_item_size > pr {
            score += 8.0; // this bin becomes dead for the next item
        }
        // harmonic class match: next item keeps residual in a friendly class
        if next_item_size <= pr && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else {
        // Last item: strongly prefer perfect fits, avoid opening bins.
        if pr == 0 {
            score -= 80.0;
        }
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening fresh bins is fine early, expensive late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
