        if mean_residual > 0.0 && mean_residual < 15.0 {
            score -= 45.0;
        }
        // Don't open a new bin when a perfect fit exists elsewhere.
        if pr == 0 && fitting_bins_count > 0 {
            score += 70.0;
        }
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.4 * open_bins_count as f64 * (1.0 - tightness);

    // Mild waste penalty scaled by stream progress.
    score += 0.15 * pr as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
