            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after the lookahead item; small slack is fine
            score += slack * 0.35;
            // bonus for near-perfect chaining
            if slack < 10.0 {
                score -= 25.0 * (1.0 - slack / 10.0);
            }
        } else {
            // next item won't fit after this placement; penalize dead space
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // last item: prefer tightest possible packing
        score -= 30.0;
    }

    // Penalize creating residual far below the mean (unusable dead space)
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual * 0.5 - post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
