    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact-ish match via integer division thresholds
            let q_next = pr / next_item_size.max(1);
            if q_next >= 1 {
                score -= 8.0 + 4.0 * (q_next.min(3) as f64);
            }
            if pr % next_item_size == 0 {
                score -= 6.0; // perfect divisibility, harmonic match
