        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bonus generally (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && pr >= 0 {
        score -= 15.0;
    }

    // New-bin candidate: prefer keeping item in an existing bin unless
    // current bin would leave large dead space while a fresh bin wastes nothing.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // but if placing in existing bins creates tiny unusable leftovers,
        // a new bin becomes attractive
        if pr > 0 && pr < 10 && bin_residual != bin_capacity {
            score -= 5.0;
