pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: progress-weighted penalty on post_residual
    // Early in the stream, tolerate larger residuals (keep bins flexible);
    // late in the stream, strongly penalize wasted space.
    let progress_coupling = (post_residual as f64 / bin_capacity as f64).powi(2)
        * (0.5 + 1.5 * progress * progress);
    score += 20.0 * progress_coupling;

    // Reward tight fits: subtract a smooth function of item_size / bin_residual ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * (fit_ratio * fit_ratio * (3.0 - 2.0 * fit_ratio.min(1.0)));

    // Penalize dead space relative to mean residual across open bins
    let dead = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dead * dead / (1.0 + progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

