    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: make empty bins moderately attractive unless open bins fit well
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
