        score -= 34.0;
    } else if pr <= 12 {
        score -= 18.0;
    } else if pr <= 18 {
        score -= 7.5;
    } else if pr <= 26 {
        score -= 2.0;
    } else if pr <= 34 {
        score += 3.0;
    }

