    // Harmonic class of the post-residual: prefer residuals that remain "usable"
    // for common item sizes. Use integer division into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Quadratic dead-space penalty: small residuals are wasted space.
    if post_residual > 0 {
        let dead = (cap / post_residual as f64 - 1.0).abs();
        score += 8.0 * (cap - post) / cap * dead;
    } else {
