    // are more likely to be filled exactly later.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 3.0; }

    // Lookahead coupling: reward if next item fits the post-residual well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 25.0; // chains a perfect fit
            } else {
                score -= 10.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

