    // Early in the stream, tolerate opening new bins (keep flexibility);
    // later, strongly consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - (bin_residual as f64) / cap);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
