            score += 12.0; // next item can't use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: be picky, penalize mediocre fits
        score += (fitting_bins_count as f64 - 3.0) * 2.0;
