        } else if next_item_size <= bin_residual {
            // Next item can't use this residual but another placement could.
            score += 9.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.10;
            if pr < 14 {
                score += 14.0;
            } else if next_item_size - pr <= 5 {
                score += 7.0;
            }
            if pr >= 18 {
                score += 3.0 + 4.0 * progress;
            }
            if next_item_size >= 45 && pr < 20 {
                score += 10.0;
            }
        }
