    // future item can fill it. Classify by capacity fractions / modulo bands.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Class A: post_residual <= 10 -> tiny dead space, nearly perfect fit.
    if post_residual <= 10 {
        score -= 60.0;
    }
    // Class B: 10 < post <= 25 -> moderately reusable zone.
    else if post_residual <= 25 {
        score -= 25.0;
    }
    // Class C: 25 < post <= 50 -> half-bin zone, very reusable.
    else if post_residual <= 50 {
        score -= 40.0;
    }
    // Class D: post > 50 -> large residual; good if more items coming.
    else {
        score -= 10.0;
    }

    // Harmonic congruence: bins whose residual sits on common item-size
    // multiples (mod 10 classes) are more likely to be filled later.
    let post_class = post_residual % 10;
    if post_class == 0 {
        score -= 12.0;
    } else if post_class <= 3 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect next fit is excellent.
            if next_item_size == post_residual {
                score -= 120.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 45.0 - slack * 0.5;
            }
        } else {
            // Next item cannot use this bin's residue: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: only exact fits matter; dead space is final waste.
        score += post * 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 55.0;
        // But if the fit leaves awkward residue while a fresh bin exists,
        // soften the bonus for very small post-residual gaps.
        if post_residual < 5 && post_residual > 0 {
            score += 20.0;
