    if bin_residual == bin_capacity {
        score += 20.0; // default penalty: prefer existing bins
        if next_item_size > 0 && post_residual >= next_item_size {
            let fill = next_item_size as f64 / post_residual as f64;
            if fill > 0.7 {
                score -= 45.0; // fresh bin pairs perfectly with next item
            }
        }
        if item_size > 70 {
            score -= 10.0; // big items deserve fresh space
        }
    }

