            let rem = pr - next_item_size;
            if rem >= 4 && rem <= 16 {
                score -= 6.0 * (1.0 - rem as f64 / 16.0);
            }
            // MUTATION: extend the useful-remainder band with a finer gradient
            // for remainders 17..=28, scaled by how close rem is to a "reusable"
            // mid-size (near 10 or 20), reinforcing the same direction.
            if rem > 16 && rem <= 28 {
                let near = (rem as f64 - 15.0).abs();
                score -= 2.5 * (1.0 - near / 13.0).max(0.0);
            }
        }
    }

