    if bin_residual == bin_capacity {
        let poor_fit = pr > 24;
        let big_item = item_size >= 50;
        if poor_fit || big_item {
            score -= 30.0;
        } else {
            score += 52.0;
        }
        if next_item_size >= 60 {
            score -= 18.0;
        }
        if progress > 0.6 {
            score += 24.0 * progress;
        }
        if open_bins_count < 4 {
            score -= 9.0;
        }
        if item_size <= 20 && pr <= 20 {
            score += 16.0;
