    // capacity-fraction buckets (dead-space classes).
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 0..7 harmonic classes of residual

    // Penalize dead space non-linearly: tiny leftovers (class 0) are nearly useless.
    match class {
        0 => score += 60.0,                 // post_residual < 12.5% : dead space
        1 => score += 18.0,                 // small but potentially usable
        2 | 3 => score -= 10.0,             // sweet spot: fits half-items
        4 => score -= 25.0,                 // ~50% residual: most reusable
        _ => score -= 5.0,                  // large residual: bin barely used
    }

    // Exact-fit reward: leftover divisible into common harmonic units.
    if post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does post_residual accommodate next item exactly?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt_post = post_residual - next_item_size;
            if nxt_post == 0 {
                score -= 40.0;              // perfect two-item chain
            } else if nxt_post <= 10 {
                score -= 20.0;              // near-perfect chain
            } else {
                score -= (nxt_post as f64).sqrt() * 2.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless residual is tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * bin_residual as f64;
    }

    // New-bin candidate handling: neutral baseline, slightly discouraged when
    // good fitting bins exist, encouraged when mean residual is fragmented.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 20.0;                  // fragmented open bins -> prefer fresh bin
