    // Mild progression scaling: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual - post_residual) as f64 * (0.3 + 0.4 * progress);

    // Tie-break toward bins below mean residual (consolidating fullness).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

