        // MUTATION: dead-space trap detection — if placing here strands a residual
        // that the next item cannot use by a wide margin, penalize proportionally.
        if next_item_size > pr && pr > 0 && pr < item_size {
            let stranded = (next_item_size - pr) as f64;
            score += 0.55 * stranded.min(30.0) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 54.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 24;
        let big_item = item_size >= 50;
        if poor_fit || big_item {
            score -= 31.0;
        } else {
            score += 54.0;
        }
        if next_item_size >= 60 {
            score -= 19.0;
        }
        if progress > 0.6 {
            score += 25.0 * progress;
        }
        if open_bins_count < 4 {
            score -= 9.5;
        }
        if item_size <= 20 && pr <= 20 {
            score += 17.0;
        }
        if progress > 0.75 && open_bins_count > 6 {
            score += 15.0;
        }
        if progress < 0.25 && open_bins_count <= 8 {
            score -= 6.5;
        }
        if item_size <= 10 && progress > 0.35 {
            score += 10.5;
        }
        if item_size >= next_item_size.saturating_sub(3) && item_size <= next_item_size + 3 && item_size >= 25 {
            score -= 7.5;
        }
        if item_size >= 30 && fitting_bins_count <= 2 {
            score -= 13.0;
        }
        if item_size >= 45 && next_item_size >= 45 && (item_size + next_item_size) as f64 <= cap {
            score -= 11.0;
        }
        // Fresh-bin appeal when the item would leave an awkward residual
        // in every fitting open bin — approximate via mean_residual proximity.
        if item_size >= 25 && mean_residual > 0.0 && (mean_residual - item_size as f64).abs() < 4.0 {
            score -= 9.5;
        }
        // MUTATION: open a fresh bin for large items when open-bin residuals are
        // fragmented — many barely-fitting bins signal poor consolidation.
        if item_size >= 55 && fitting_bins_count >= 3 {
            score -= 8.0;
        }
    }

    // Harmonic band match when multiple bins fit.
    if next_item_size > 0 && pr >= next_item_size && fitting_bins_count > 1 {
        score -= 6.5 + 3.0 * (1.0 - progress);
    }

    // Exact-fill drive.
    if pr == 0 && bin_residual < bin_capacity {
        score -= 21.0 + 15.0 * progress;
    }

    // Avoid awkward-middle residuals, scaled by how much next item misses.
    if pr >= 17 && pr <= 23 && next_item_size > pr {
        score += 8.5;
    }

    // Penalize residuals that no plausible upcoming item can use.
    if pr > 30 && next_item_size > pr {
        score += 0.28 * (pr - 30) as f64;
    }

    // MUTATION: mean-residual gap coupling — when this bin's post-residual sits
    // far above the fleet mean, it is likely orphan dead space; nudge score up.
    if pr > 0 && mean_residual > 0.0 && pr as f64 > mean_residual + 12.0 {
        score += 0.18 * (pr as f64 - mean_residual - 12.0);
    }

    // Consolidation pressure.
    score -= 0.07 * mean_residual;

    // Progress-scaled tightening.
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer small post-residual (tight fit), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in stream, tight fits matter more; early on, slack is acceptable.
    let tightness = 1.0 - (pr / cap); // 1 = perfect fit
    score += 40.0 * tightness.powi(3) * (0.3 + 0.7 * progress);

    // Reward near-perfect fits strongly (smooth bump around small pr).
    score -= 25.0 * (-(pr / 8.0).powi(2)).exp();

    // Penalize dead space that can't fit typical items (smooth quadratic).
    if pr > 0.0 {
        score += 0.15 * (pr / 10.0).powi(2) * (1.0 - progress);
    }

    // Lookahead: bonus if next item fits the post-residual (smooth).
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0);
        score -= 15.0 * (-(fits_next / 12.0).powi(2)).exp();
        // Penalize leaving residual just below next item size (blocking).
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap < 30.0 {
            score += 8.0 * (1.0 - gap / 30.0).powi(2);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if is_new_bin {
        score += 20.0 + 30.0 * (1.0 - progress);
        // But if no open bin fits well, allow new bin (handled via others' scores).
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild preference to fill bins with larger residuals when many bins open.
    score += 0.02 * (open_bins_count as f64) * (pr / cap);

    // Mean residual context: deviating toward small residual is good.
    score += 0.1 * (pr - mean_residual).abs().powi(2).sqrt() * (1.0 - progress);

    score
}

