    // exceeds both the next item and the observed mean residual, i.e. space
    // nothing in the near stream is likely to use.
    if pr > 0 && next_item_size > pr && pr as f64 > mean_residual {
        score += 0.35 * (pr as f64 - mean_residual);
    }

    // Consolidation pressure.
    score -= 0.07 * mean_residual;

    // Progress-scaled tightening.
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, mild penalty for large residuals (keep space flexible);
    // late in the stream, strongly reward tight packing (small post_residual).
    let tightness = (pr_norm - 0.5) * (pr_norm - 0.5);
    let phase = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 30.0 * tightness * (1.0 - phase);
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * phase;

    // Dead-space avoidance: quadratic penalty when residual becomes too small to be useful
    if pr > 0.0 {
        let dead = (1.0 - pr / 20.0).max(0.0);
        score += 8.0 * dead * dead;
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + phase);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 6.0 * (1.0 - fits_next) * (1.0 + phase);
        } else {
            score += 3.0 * (-fits_next);
        }
    }

    // Mean-residual coupling: penalize bins far from the mean (smooth)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Mild new-bin preference early, mild open-bin preference late
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - phase);
        score += 4.0 * phase;
    }

    score
}

