    let class_penalty: [f64; 9] = [0.0, 12.0, 8.0, 5.0, 3.0, 1.5, 0.5, 0.0, 0.0];
    score += class_penalty[class.min(8) as usize];

    // Perfect fills are gold
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo arithmetic: leftover that can't fit the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 14.0; // dead space
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item fills a class exactly?
            let nxt_mod = post_residual % next_item_size.max(1);
            score -= 6.0 - (nxt_mod as f64) * 0.25;
            if next_item_size == post_residual {
                score -= 10.0; // exact chained fill
            }
        } else {
            score += 4.0; // lookahead won't reuse this bin
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin, more when many bins already open
        score += 20.0 + 2.0 * open_bins_count as f64;
        // but if current item is huge and leaves awkward remainder, new bin may win
        let rem = bin_capacity - item_size;
        if rem < 20 {
            score -= 18.0;
