    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    // Fraction-of-capacity smooth term: reward tight fits
    score -= (1.0 - pr / cap) * 3.0;

