        score += (10 - post_residual) as f64 * 6.0;
    }

    // Modulo classes on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are reusable -> reward.
    if post_residual % 10 == 0 { score -= 15.0; }
    if post_residual % 25 == 0 { score -= 10.0; }
    if post_residual % 50 == 0 { score -= 10.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
