            let gap = next_item_size - post_residual;
            if gap <= 10 { score += gap as f64 * 4.0; }
        }
    }

    // Integer-division threshold on bin_residual: bins with large residual are
    // precious; wasting them on small items is bad.
    let half = bin_capacity / 2;
    if bin_residual > half && item_size < bin_capacity / 4 {
        score += 12.0;
