    if pr > 0 && pr < 9 {
        score += 42.0;
    } else if pr < 18 {
        score += 13.0;
    } else if pr % 20 == 0 {
        score -= 20.0;
    } else if pr % 25 == 0 {
        score -= 10.0;
    }

    // Residual-fraction coupling.
    if frac > 0.5 {
        score += 13.5 * (frac - 0.5);
    } else if frac < 0.15 && pr > 0 {
        score -= 8.0 * (0.15 - frac) * 10.0;
    }

    // Dead-space ratio vs next item.
    if next_item_size > pr && pr > 0 {
        let dead_ratio = 1.0 - pr as f64 / (next_item_size as f64).max(1.0);
        score += 11.0 * dead_ratio * frac.max(0.2);
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 52.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 27.0 + slack.min(24.0);
        } else if next_item_size > pr && next_item_size <= bin_residual {
            score += 9.0;
        }
        let two_step = pr.saturating_sub(next_item_size);
        if next_item_size <= pr && (two_step % 10 == 0 || (two_step % 5 == 0 && two_step <= 20)) {
            score -= 18.0;
        }
        if next_item_size > pr && pr < 14 {
            score += 14.0;
        }
        if next_item_size > pr && pr >= 14 && (next_item_size - pr) <= 5 {
            score += 7.0;
        }
        let after = pr.saturating_sub(next_item_size);
        if after > 0 && after <= 8 {
            score -= 13.0;
        } else if after > 8 && after <= 16 {
            score -= 5.5;
        }
        if next_item_size > pr && next_item_size >= 45 && pr < 20 {
            score += 10.0;
        }
        if next_item_size >= 10 && next_item_size <= 40 && (pr as i64 - next_item_size as i64).abs() <= 2 && pr > 0 {
            score -= 9.0;
        }
        if next_item_size < pr && pr - next_item_size >= next_item_size / 2 {
            score -= 4.5;
        }
        if next_item_size > pr && pr >= 18 {
            score += 3.0 + 4.0 * progress;
        }
        // Two-step lookahead — reward residuals that can host the next item AND
        // leave a useful remainder (>= 4) rather than a useless sliver.
        if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem >= 4 && rem <= 16 {
                score -= 6.0 * (1.0 - rem as f64 / 16.0);
            }
        }
        // MUTATION: refine two-step quality — a remainder exactly matching a
        // small-item band (<= 10) is highly reusable; amplify the reward.
        if next_item_size < pr {
            let rem = pr - next_item_size;
            if rem >= 1 && rem <= 10 {
                score -= 5.0 + 0.6 * (10 - rem) as f64;
            }
        }
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 52.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 24;
        let big_item = item_size >= 50;
        if poor_fit || big_item {
            score -= 30.0;
        } else {
            score += 52.0;
        }
        if next_item_size >= 60 {
            score -= 18.0;
        }
        if progress > 0.6 {
            score += 24.0 * progress;
        }
        if open_bins_count < 4 {
            score -= 9.0;
        }
        if item_size <= 20 && pr <= 20 {
            score += 16.0;
        }
        if progress > 0.75 && open_bins_count > 6 {
            score += 14.0;
        }
        if progress < 0.25 && open_bins_count <= 8 {
            score -= 6.0;
        }
        if item_size <= 10 && progress > 0.35 {
            score += 10.0;
        }
        if item_size >= next_item_size.saturating_sub(3) && item_size <= next_item_size + 3 && item_size >= 25 {
            score -= 7.0;
        }
        if item_size >= 30 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if item_size >= 45 && next_item_size >= 45 && (item_size + next_item_size) as f64 <= cap {
            score -= 10.0;
        }
        // Fresh-bin appeal when the item would leave an awkward residual in every
        // fitting open bin — approximate via mean_residual proximity.
        if item_size >= 25 && mean_residual > 0.0 && (mean_residual - item_size as f64).abs() < 4.0 {
            score -= 9.0;
        }
        // MUTATION: open a fresh bin when every fitting open bin would strand a
        // large unusable residual (pr > item_size + 30) — avoid fragmentation.
        if fitting_bins_count > 0 && item_size <= 40 && next_item_size <= 40 {
            score -= 4.0;
        }
    }

    // Harmonic band match when multiple bins fit.
    if next_item_size > 0 && pr >= next_item_size && fitting_bins_count > 1 {
        score -= 6.0 + 3.0 * (1.0 - progress);
    }

    // Exact-fill drive.
    if pr == 0 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Avoid awkward-middle residuals, scaled by how much next item misses.
    if pr >= 17 && pr <= 23 && next_item_size > pr {
        score += 8.0;
    }

    // Penalize residuals that no plausible upcoming item can use — residuals
    // above the usable band when next item overshoots.
    if pr > 30 && next_item_size > pr {
        score += 0.25 * (pr - 30) as f64;
    }
    // MUTATION: large stranded residuals are nearly unreachable regardless of the
    // next item — apply a global progressive penalty above the 50-unit mark.
    if pr > 50 {
        score += 0.35 * (pr - 50) as f64;
    }
    // MUTATION: when several bins fit, prefer the one whose post-residual best
    // matches the next item's size class — mild competitive discount.
    if fitting_bins_count > 2 && next_item_size > 0 && pr >= next_item_size {
        let diff = (pr - next_item_size) as f64;
        if diff <= 12.0 {
            score -= 4.0 * (1.0 - diff / 12.0);
        }
    }

    // Consolidation pressure.
    score -= 0.07 * mean_residual;

    // Progress-scaled tightening.
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item (perfect two-item fill), scaled by lookahead validity.
    if next_item_size > 0 {
        let lookahead_weight = if step_index + 2 < total_items { 1.0 } else { 0.5 };
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (diff == 0) subtracts a large bonus; near matches get partial credit.
        score -= 40.0 * lookahead_weight * (1.0 - diff / 100.0).max(0.0);

        // Penalize leaving a residual that is too small for the next item but
        // still wastes capacity (dead space in (0, next_item_size) range).
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 8.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare post_residual against mean residual: leaving below-average
    // residual is good (tight packing), above-average is wasteful.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.35 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty for very tight fits that leave unusable slivers
    // (< 10, minimum item size), unless next item can use it.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 12.0;
    }

    // Mild preference for filling more crowded bins first when many bins open.
    score += 0.15 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when open bins would leave large waste.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

