        score -= 60.0;
    } else if tightness < 0.15 {
        score -= 20.0;
    }

    // Penalize creating tiny unusable slivers (dead space nothing later can use).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: penalize if the next item could have fit in the current residual
    // but won't fit after placing here (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 12.0;
        }
        // Reward if next item still fits after placement (keeps bin usable).
        if next_item_size <= post_residual {
            score -= 8.0;
        }
