    // favor bins with below-average residual (filling emptier bins first).
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 3.0;
    } else if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

