    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // moderately awkward residual
    }

    // Lookahead coupling: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * (next_item_size as f64);
        } else if bin_residual >= next_item_size && post_residual >= next_item_size {
            score -= 2.0;
        }
        // Penalize if placing item blocks the next item in this bin but next is small enough elsewhere
        if post_residual < next_item_size && next_item_size <= bin_capacity {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: mild normalization toward tightest fits among many candidates
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced over time if many bins already open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 8.0 * progress;
        // if mean residual across open bins is large, opening new bin is wasteful
        score += 0.15 * mean_residual;
        // if few bins fit the item, opening a bin is more acceptable
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
        // large items prefer fresh bins when residuals are fragmented
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> consolidate
    if open_bins_count > 3 && mean_residual < 25.0 {
        score -= 5.0;
    }

    // Time horizon: early in stream, be conservative (avoid over-tight packing that strands space);
    // late in stream, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

