    if pr > 0 && pr < 9 {
        score += 42.0;
    } else if pr < 18 {
        score += 13.0;
    } else if pr % 20 == 0 {
        score -= 20.0;
    } else if pr % 25 == 0 {
        score -= 10.0;
    }

    // Residual-fraction coupling.
    if frac > 0.5 {
        score += 13.5 * (frac - 0.5);
    } else if frac < 0.15 && pr > 0 {
        score -= 8.0 * (0.15 - frac) * 10.0;
    }

