    if pr >= 17 && pr <= 23 && next_item_size > pr {
        score += 8.0;
    }

    // Penalize residuals that no plausible upcoming item can use — residuals above
    // the 60th-percentile-ish band when next item overshoots.
    if pr > 30 && next_item_size > pr {
        score += 0.25 * (pr - 30) as f64;
