    } else {
        // Last item: prefer exact fill above all.
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, opening a new bin
    // would waste the residual entirely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 > 2.0 + 4.0 * progress;
