}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit lookahead: if the next item exactly fills the post-residual,
    // strongly reward this bin (chained 2-step fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }

    // Next item fits into the remaining space with small slack: reward proportionally.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize dead space more aggressively.
        score += 8.0;
    }

    // Penalize small post-residuals that are unlikely to be usable (dead space),
    // but only if they don't match the next item (already handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that are already more filled
    // (lower residual than average) to consolidate waste.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Prefer using existing bins over opening new ones as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
