    // Dead-space penalty: leftover too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic class logic: leftover that is a clean fraction of capacity
    // (e.g. 50, 25, 20, 10) is more reusable than awkward remainders.
    let harmonic_bonus = if post_residual == bin_capacity / 2 {
        40.0
    } else if post_residual == bin_capacity / 4 {
        25.0
    } else if post_residual == bin_capacity / 5 {
        20.0
    } else if post_residual % 10 == 0 {
        12.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Modulo coupling between post_residual and next_item_size:
    // reward leftovers that exactly accommodate the lookahead item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // leftover can host the next item: mild reward, scaled by how snug
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1.0) as f64);
        } else {
            // next item cannot fit here: penalize proportional to wasted fraction
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Integer-division threshold: leftover in the "useless band" (1..10)
    // relative to the harmonic granularity of 10 gets extra penalty.
    if post_residual % 10 != 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and leftovers elsewhere are awkward.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= bin_capacity / 2 {
