    } else if post_frac < 0.15 && pr > 0 {
        score -= 8.0 * (0.15 - post_frac) * 10.0;
    }

    // Dead-space ratio vs next item.
    if next_item_size > pr && pr > 0 {
        let dead_ratio = 1.0 - pr as f64 / (next_item_size as f64).max(1.0);
        score += 11.0 * dead_ratio * post_frac.max(0.2);
    }

    // Lookahead: chain the next item into this residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 52.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 27.0 + slack.min(24.0);
            let rem = pr - next_item_size;
            if rem >= 4 && rem <= 16 {
                score -= 6.5 * (1.0 - rem as f64 / 16.0);
            }
            if rem % 10 == 0 || (rem % 5 == 0 && rem <= 20) {
                score -= 18.0;
            }
            if rem >= next_item_size / 2 {
                score -= 4.5;
            }
            // MUTATION: two-step lookahead — residual must host next item AND
            // leave a usable remainder, not a dead sliver.
            if rem < 3 {
                score += 9.0;
            }
        } else {
            score += (next_item_size - pr) as f64 * 0.10;
            if pr < 14 {
                score += 14.0;
            } else if next_item_size - pr <= 5 {
                score += 7.0;
            }
            if pr >= 18 {
                score += 3.0 + 4.0 * progress;
            }
            if next_item_size >= 45 && pr < 20 {
                score += 10.0;
            }
            // MUTATION: next item fits this bin exactly after placement.
            if next_item_size <= bin_residual {
                score += 9.0;
            }
        }
        if next_item_size >= 10 && next_item_size <= 40 && pr > 0 && (pr as i64 - next_item_size as i64).abs() <= 2 {
            score -= 9.0;
        }
        let after = pr.saturating_sub(next_item_size);
        if after > 0 && after <= 8 {
            score -= 13.0;
        } else if after > 8 && after <= 16 {
            score -= 5.5;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 52.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let poor_fit = pr > 24;
        let big_item = item_size >= 50;
        if poor_fit || big_item {
            score -= 30.0;
        } else {
            score += 52.0 + mean_residual * 0.20 + (open_bins_count as f64) * 0.4;
        }
        if next_item_size >= 60 {
            score -= 18.0;
        }
        if progress > 0.6 {
            score += 24.0 * progress;
        }
        if open_bins_count < 4 {
            score -= 9.0;
        }
        if item_size <= 20 && pr <= 20 {
            score += 16.0;
        }
        if progress > 0.75 && open_bins_count > 6 {
            score += 14.0;
        }
        if progress < 0.25 && open_bins_count <= 8 {
            score -= 6.0;
        }
        if item_size <= 10 && progress > 0.35 {
            score += 10.0;
        }
        if item_size >= 30 && fitting_bins_count <= 2 {
            score -= 12.0;
        }
        if item_size >= 45 && next_item_size >= 45 && (item_size + next_item_size) as f64 <= cap {
            score -= 10.0;
        }
        // Fresh-bin appeal when item size is near mean residual —
        // suggests an open bin exists that would be filled almost exactly.
        if item_size >= 25 && mean_residual > 0.0 && (mean_residual - item_size as f64).abs() < 4.0 {
            score -= 9.0;
        }
        // When the next item is large, avoid wasting a fresh bin's
        // full capacity on a small item now.
        if next_item_size >= item_size * 2 && next_item_size >= 40 {
            score += 7.0;
        }
        // MUTATION: item pairs with next item exactly in a fresh bin.
        if item_size >= 25 && (item_size as i64 - next_item_size as i64).abs() <= 3 {
            score -= 7.0;
        }
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.08;
    }

    // Harmonic band match when multiple bins fit.
    if next_item_size > 0 && pr >= next_item_size && fitting_bins_count > 1 {
        score -= 6.0 + 3.0 * (1.0 - progress);
    }

    // Avoid awkward-middle residuals when next item overshoots.
    if pr >= 17 && pr <= 23 && next_item_size > pr {
        score += 8.0;
    }
    if pr > 30 && next_item_size > pr {
        score += 0.25 * (pr - 30) as f64;
    }

    // Exact-fill drive.
    if pr == 0 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Consolidation pressure.
    score -= 0.07 * mean_residual;

    // Late-stream tightening.
    score -= progress * 6.0 * (post_frac * 10.0).min(1.0);
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows super-linearly for large dead space.
    let mut score = pr + 60.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits: coupling of post_residual with item size.
    let tightness = 1.0 - norm_pr; // high when item fills bin well
    score -= 30.0 * tightness * tightness * (item_size as f64 / cap);

    // Stream-progress coupling: as the stream advances, waste matters more,
    // so amplify post-residual penalty smoothly.
    score += 25.0 * progress * norm_pr * (mean_residual / cap).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 + 20.0 * progress;
    }

    // Lookahead: if next item could use the post-residual, reward leaving it.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // post-residual too small for next item: penalize dead space smoothly.
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly, more later in the stream.
        score += 35.0 + 40.0 * progress;
        // If few bins can fit the item, opening a new bin is less bad.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Mild penalty for proliferating open bins early on.
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
