pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize residual, but weight by how "usable" that residual is.
    // Harmonic classes: residuals divisible by small item sizes are more usable.
    let mut usable = 0u32;
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            usable += 1;
        }
    }
    score -= 3.0 * usable as f64;

    // Dead-space penalty: tiny post_residuals that nothing (>= min size 10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mildly penalize wasting the slot.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin when mean residual is small (bins nearly full).
        score -= (mean_residual / bin_capacity as f64) * 25.0;
        // Allow new bin early in stream (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer tighter bins among open bins: closer residual to item size is better.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Harmonic threshold: post_residual in [10, 30) is a "sweet spot" class.
    if post_residual >= 10 && post_residual < 30 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
