    } else if pr < 18 {
        score += 13.0;
    }

    // Divisibility bonuses: residuals that future items may exactly fill.
    if pr % 20 == 0 {
        score -= 20.0;
    } else if pr % 25 == 0 {
        score -= 10.0;
    }

    // Residual-fraction coupling.
    if frac > 0.5 {
        score += 14.0 * (frac - 0.5);
    } else if frac < 0.15 && pr > 0 {
        score -= 80.0 * (0.15 - frac);
    }

    // Lookahead with next item.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 650.0; // chain fit: ideal
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / cap);
            let rem = pr - next_item_size;
            if rem >= 4 && rem <= 16 {
                score -= 7.0 * (1.0 - rem as f64 / 16.0);
            }
            if rem % 10 == 0 || (rem % 5 == 0 && rem <= 20) {
                score -= 18.0;
            }
            if after_is_small(rem) {
                score -= 10.0;
            }
        } else {
            let dead = (next_item_size - pr) as f64;
            score += 2.0 * dead;
            if pr < 14 {
                score += 14.0;
            } else if dead <= 5.0 {
                score += 7.0;
            }
            if next_item_size >= 45 && pr < 20 {
