        if next_item_size >= 10 && next_item_size <= 40 && (pr as i64 - next_item_size as i64).abs() <= 2 && pr > 0 {
            score -= 9.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 420.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && pr < next_item_size && pr > 0;
        let big_item = item_size >= 50;
        if fitting_bins_count <= 1 || poor_fit || big_item {
            score -= 330.0;
        } else {
            score += 500.0;
        }
        if next_item_size >= 60 {
            score -= 18.0;
        }
        if progress > 0.6 {
