    score -= 0.07 * mean_residual;

    // Early-stream structure building + progress-scaled tightening.
    score -= 100.0 * (1.0 - progress) * frac;
    score += (open_bins_count as f64) * 0.28;
    score *= 1.0 - 0.14 * progress;

    score
}

#[inline]
fn after_is_small(rem: u32) -> bool {
    rem > 0 && rem <= 8
}
